#!/usr/bin/env node
// Generates src/renderer/src/styles/tokens.css from tokens.figma.json (an export of the Figma
// variables + effect styles in file 9dxNGKCuO9PRboqKbLBvIB). Figma is the source of truth:
// change a value there, re-export the JSON, run `npm run tokens`. Do not edit tokens.css by hand.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const dir = path.join(root, 'src/renderer/src/styles')
const src = JSON.parse(fs.readFileSync(path.join(dir, 'tokens.figma.json'), 'utf8'))

const PRIM = 'Color / Primitives', SEM = 'Color / Semantic', DIM = 'Dimension'
const prim = src.c[PRIM].v, sem = src.c[SEM].v, dim = src.c[DIM].v
const semModes = src.c[SEM].m // e.g. Light, Dark, Paper

const fromCode = (code) => (code && code.match(/^var\((--[\w-]+)\)$/) || [])[1]
const slug = (name) => '--' + name.replace(/\//g, '-')

// css names: semantic + dimension use their code syntax; primitives use their Figma name,
// suffixed -base when that would clash with a semantic token (kind/prompt, brand/claude, …)
const semNames = new Set(Object.values(sem).map(([, code], i) => fromCode(code)).filter(Boolean))
const primCss = {}
for (const name of Object.keys(prim)) { const n = slug(name); primCss[name] = semNames.has(n) ? n + '-base' : n }
const dimCss = {}
for (const [name, [, code]] of Object.entries(dim)) dimCss[name] = fromCode(code) || slug(name)
const semCss = {}
for (const [name, [, code]] of Object.entries(sem)) semCss[name] = fromCode(code) || slug(name)

const color = (v) => v.replace(/rgba\((\d+),(\d+),(\d+),([\d.]+)\)/, (_, r, g, b, a) => `rgba(${r}, ${g}, ${b}, ${Math.abs(+a - Math.round(+a * 100) / 100) < 0.004 ? Math.round(+a * 100) / 100 : +a})`)
const semValue = (v) => (typeof v === 'string' && v.startsWith('@') ? `var(${primCss[v.slice(1)]})` : color(String(v)))
const CODE_FAMILY = { 'Google Sans Flex': 'Google Sans' }
const STACK = {
  // The app loads "Google Sans" from Google Fonts; Figma's library only has Google Sans Flex, so the
  // Figma value is kept as the second choice. CODE_FAMILY maps a Figma family to what the app loads first.
  'font-family/ui': (v) => `${CODE_FAMILY[v] ? `"${CODE_FAMILY[v]}", ` : ''}"${v}", -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif`,
  'font-family/mono': (v) => `"${v}", ui-monospace, SFMono-Regular, Menlo, monospace`
}
const dimValue = (name, v) => {
  if (typeof v === 'string' && v.startsWith('@')) return `var(${dimCss[v.slice(1)]})`
  if (STACK[name]) return STACK[name](v)
  if (typeof v === 'number') {
    const group = name.split('/')[0]
    if (group === 'font-weight' || group === 'z') return String(v)
    if (group === 'opacity') return String(v / 100) // Figma stores opacity as 0–100
    if (group === 'letter-spacing') return `${v / 100}em` // Figma: percent of font size
    if (group === 'duration') return `${v}ms`
    if (group === 'line-height') return v < 4 ? String(v) : `${v}px` // multipliers stay unitless
    return `${v}px`
  }
  return String(v)
}
const group = (entries) => {
  const out = []; let last = null
  for (const [k, line] of entries) { const g = k.split('/')[0]; if (last !== null && g !== last) out.push(''); out.push(line); last = g }
  return out
}
const semBlock = (mode, indent) => {
  const i = semModes.indexOf(mode)
  return group(Object.entries(sem).map(([name, v]) => [name, `${indent}${semCss[name]}: ${semValue(v[2 + i])};`]))
}
const changedFromLight = (mode) => Object.entries(sem).filter(([, v]) => v[2 + semModes.indexOf(mode)] !== v[2])

const L = []
L.push('/* Troupe design tokens — GENERATED by scripts/build-tokens.mjs from tokens.figma.json.')
L.push('   Source of truth: Figma file 9dxNGKCuO9PRboqKbLBvIB (variables + effect styles). Do not edit by hand:')
L.push('   change Figma, re-export tokens.figma.json, run `npm run tokens`.')
L.push('   Layers: primitives (raw ramps, used only here) → semantic (what the UI uses) → modes (light, dark, paper). */')
L.push('', ':root {', '  /* ---------- primitives ---------- */')
L.push(...group(Object.entries(prim).map(([name, v]) => [name, `  ${primCss[name]}: ${color(v[2])};`])))
L.push('', '  /* ---------- semantic — light (default) ---------- */')
L.push(...semBlock(semModes[0], '  '))
L.push('', '  /* ---------- elevation ---------- */')
for (const [name, v] of Object.entries(src.fx)) L.push(`  --shadow-${name.split('/')[1].toLowerCase()}: ${v.replace(/\b0px\b/g, '0').replace(/rgba\((\d+),(\d+),(\d+),([\d.]+)\)/g, 'rgba($1, $2, $3, $4)')};`)
L.push('', '  /* ---------- dimension: space, radius, type, icons, layout ---------- */')
L.push(...group(Object.entries(dim).map(([name, v]) => [name, `  ${dimCss[name]}: ${dimValue(name, v[2])};`])))
L.push('}')
const dark = semModes.find((m) => /dark/i.test(m)), paper = semModes.find((m) => /paper/i.test(m))
if (dark) {
  const lines = changedFromLight(dark).map(([name, v]) => `${semCss[name]}: ${semValue(v[2 + semModes.indexOf(dark)])};`)
  L.push('', '/* ---------- semantic — dark ----------', '   For the OS setting only when the user hasn\'t picked a theme (DX-005), and always for explicit dark. */')
  L.push('@media (prefers-color-scheme: dark) {', '  :root:not([data-theme]) {', ...lines.map((l) => '    ' + l), '  }', '}')
  L.push(':root[data-theme="dark"] {', ...lines.map((l) => '  ' + l), '}')
}
if (paper) {
  const lines = changedFromLight(paper).map(([name, v]) => `${semCss[name]}: ${semValue(v[2 + semModes.indexOf(paper)])};`)
  L.push('', '/* ---------- semantic — paper ----------', '   The artifact viewer reads as a white page in every theme. Opt in with data-surface="paper".', '   Lists every semantic token so a dark ancestor never leaks in. */')
  const all = Object.entries(sem).map(([name, v]) => `${semCss[name]}: ${semValue(v[2 + semModes.indexOf(paper)])};`)
  L.push('[data-surface="paper"] {', ...all.map((l) => '  ' + l), '  background: var(--surface-white); /* artifacts are always a white page */', '  color: var(--text-primary);', '}')
  void lines
}
fs.writeFileSync(path.join(dir, 'tokens.css'), L.join('\n') + '\n')

// tokens.ts — numeric dimension tokens for TS that needs numbers (canvas geometry, inline maths).
const resolveDim = (v) => (typeof v === 'string' && v.startsWith('@') ? resolveDim(dim[v.slice(1)][2]) : v)
const nums = Object.entries(dim).filter(([, v]) => v[0] === 'F').map(([name, v]) => `  '${name}': ${resolveDim(v[2])},`)
fs.writeFileSync(path.join(dir, 'tokens.ts'), [
  '// GENERATED by scripts/build-tokens.mjs from tokens.figma.json — do not edit. Values are raw Figma numbers',
  '// (px for sizes; opacity 0–100; letter-spacing percent; duration ms).',
  'export const dim = {', ...nums, '} as const', 'export type DimToken = keyof typeof dim', ''].join('\n'))

// guard: every var(--x) used by the renderer must be defined
const defined = new Set([...L.join('\n').matchAll(/(--[\w-]+):/g)].map((m) => m[1]))
const runtime = new Set(['--kind', '--select', '--chat-fs', '--artifact-fs']) // set at runtime / per component
const missing = new Set()
const walk = (d) => { for (const f of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, f.name); if (f.isDirectory()) walk(p); else if (/\.(css|tsx?)$/.test(f.name) && f.name !== 'tokens.css') for (const m of fs.readFileSync(p, 'utf8').matchAll(/var\((--[\w-]+)/g)) if (!defined.has(m[1]) && !runtime.has(m[1]) && !m[1].endsWith('-')) missing.add(`${m[1]}  (${path.relative(root, p)})`) } }
walk(path.join(root, 'src/renderer/src'))
if (missing.size) { console.error('tokens.css: undefined tokens used in the renderer:\n  ' + [...missing].join('\n  ')); process.exit(1) }
console.log(`tokens.css written: ${Object.keys(prim).length} primitives, ${Object.keys(sem).length} semantic × ${semModes.length} modes, ${Object.keys(dim).length} dimension, ${Object.keys(src.fx).length} shadows`)
